-- Medicines
-- ---------------------------------------------------------------

-- ---------------------------------------------------------------
-- Medicine batches (opening stock, from current Medicine Stock Report)
-- ---------------------------------------------------------------

-- ---------------------------------------------------------------
-- Opening stock ledger entries (one RECEIPT row per batch above)
-- ---------------------------------------------------------------
SELECT mb.medicine_id, mb.id, 'PURCHASE', mb.quantity_on_hand, 0, mb.quantity_on_hand, 'PURCHASE', mb.id, mb.batch_no, mb.created_date, mb.created_date
FROM medicine_batches mb;

